={{ (() => {
  const req = $('Build Answer Request').first().json;
  const answer = String($json.choices?.[0]?.message?.content ?? '').trim();
  if (!answer) return 'No he podido generar una respuesta ahora mismo. Inténtalo de nuevo en unos minutos.';
  const note = req.partial
    ? '\n\nℹ️ Hay demasiados correos para revisarlos todos a la vez: he consultado ' + req.included + ' de ' + req.total + ' seleccionados por palabras clave. La respuesta puede estar incompleta.'
    : '';
  return answer.slice(0, 4000 - note.length) + note;
})() }}
